import { useState, useEffect } from "react";
import axios from "axios";
import HouseCard from "../components/HouseCard";
import ChatBox from "../components/ChatBox";

function Homes() {
  const [homes, setHomes] = useState([]);
  const [chatHomeId, setChatHomeId] = useState(null);
  const [chatOwnerName, setChatOwnerName] = useState("");
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const userId = localStorage.getItem("userId");

  useEffect(() => {
    if (!userId) {
      window.location.href = "/login";
      return;
    }

    const fetchHomes = async () => {
      setLoading(true);
      try {
        const res = await axios.get("http://localhost:5000/homes");
        console.log("Fetched homes data:", res.data);
        if (Array.isArray(res.data)) {
          setHomes(res.data);
        } else {
          console.error("Unexpected data format:", res.data);
          setHomes([]);
        }
      } catch (error) {
        console.error("Error fetching homes:", error.message);
        setError(error.message);
      } finally {
        setLoading(false);
      }
    };

    fetchHomes();
  }, [userId]);

  const openChat = (homeId, ownerName) => {
    setChatHomeId(homeId);
    setChatOwnerName(ownerName);
    setIsChatOpen(true);
  };

  const closeChat = () => {
    setIsChatOpen(false);
    setChatHomeId(null);
    setChatOwnerName("");
  };

  return (
    <div
      className="min-h-screen bg-cover bg-center p-10"
      style={{ backgroundImage: "url(http://localhost:5000/light.jpg)" }}
    >
      <h1 className="text-4xl text-center mb-8 text-white text-shadow-lg">
        Available Homes
      </h1>
      {loading ? (
        <div className="text-center text-white">Loading...</div>
      ) : error ? (
        <div className="text-center text-red-500">Error: {error}</div>
      ) : homes.length === 0 ? (
        <div className="text-center text-white">No homes available.</div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-10 max-w-7xl mx-auto">
          {homes.map((home) => (
            <HouseCard key={home.id} home={home} openChat={openChat} />
          ))}
        </div>
      )}
      <ChatBox
        homeId={chatHomeId}
        ownerName={chatOwnerName}
        isOpen={isChatOpen}
        onClose={closeChat}
      />
    </div>
  );
}

export default Homes;
